            countH[height[u]]++;
        }
        return totalFlow;
    }

    int computeMaxFlow(int s_, int t_) {
        s = s_; t = t_;
        memset(flow, 0, sizeof(flow));
        memset(height, 0, sizeof(height));
        memset(countH, 0, sizeof(countH));
        for (int i = 0; i <= totalNodes; i++) height[i] = 0;
        countH[0] = totalNodes;
        int totalFlow = 0;
        while (height[s] < totalNodes) {
            totalFlow += pushFlow(s, INF);
        }
        return totalFlow;
    }
};

