import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 210;
    static final int INF = 0x3f3f3f3f;
    static int n, T;
    static int startX, startY;
    static int[] dirX = {0, 0, -1, 1};
    static int[] dirY = {-1, 1, 0, 0};
    static char[][] gridA = new char[MAXN][MAXN];
    static char[][] gridB = new char[MAXN][MAXN];
    static int[][] distMap = new int[MAXN][MAXN];
    static int[][] visited = new int[MAXN][MAXN];

    static class FlowSolver {
        int[][] capacity = new int[MAXN][MAXN];
        int[][] flow = new int[MAXN][MAXN];
        int[][] adj = new int[MAXN][MAXN];
        int[] degree = new int[MAXN];
        int totalNodes, s, t;
        int[] height = new int[MAXN];
        int[] countH = new int[MAXN];

        void setup(int n) {
            totalNodes = n;
            for (int i = 0; i <= n; i++) {
                Arrays.fill(capacity[i], 0);
                Arrays.fill(adj[i], 0);
                degree[i] = 0;
            }
            Arrays.fill(height, 0);
            Arrays.fill(countH, 0);
        }

        void addEdge(int u, int v, int c) {
            capacity[u][v] += c;
            if (adj[u][v] == 0) {
                adj[u][v] = 1;
                degree[u]++;
            }
        }

        int pushFlow(int u, int flowIn) {
            if (u == t) return flowIn;
            int totalFlow = 0;
            for (int v = 0; v < totalNodes; v++) {
                if (capacity[u][v] - flow[u][v] > 0 && height[u] == height[v] + 1) {
                    int pushed = Math.min(flowIn, capacity[u][v] - flow[u][v]);
                    int pushedAmount = pushFlow(v, pushed);
                    if (pushedAmount > 0) {
                        flow[u][v] += pushedAmount;
                        flow[v][u] -= pushedAmount;
                        totalFlow += pushedAmount;
                        flowIn -= pushedAmount;
                        if (flowIn == 0) break;
                    }
                }
            }
            if (totalFlow == 0) {
                int minH = totalNodes;
                for (int v = 0; v < totalNodes; v++) {
                    if (capacity[u][v] - flow[u][v] > 0) minH = Math.min(minH, height[v]);
                }
                if (--countH[height[u]] == 0) height[s] = totalNodes;
                height[u] = minH + 1;
                countH[height[u]]++;
            }
            return totalFlow;
        }

        int computeMaxFlow(int s_, int t_) {
            s = s_; t = t_;
            for (int i = 0; i <= totalNodes; i++) {
                Arrays.fill(flow[i], 0);
                height[i] = 0;
            }
            Arrays.fill(countH, 0);
            for (int i = 0; i <= totalNodes; i++) height[i] = 0;
            countH[0] = totalNodes;
            int totalFlow = 0;
            while (height[s] < totalNodes) {
                totalFlow += pushFlow(s, INF);
            }
            return totalFlow;
        }
    }

    static class Cell {
        int row, col, dist;
        Cell(int r, int c, int d) {
            row = r; col = c; dist = d;
        }
    }

    static int getID(int i, int j) {
        return (i - 1) * n + j;
    }

    static boolean validPos(int x, int y) {
        return x >= 1 && x <= n && y >= 1 && y <= n;
    }

    static void computeDist1(FlowSolver solver, int startX, int startY, int T) {
        Queue<Cell> q = new LinkedList<>();
        Cell c = new Cell(startX, startY, 0);
        q.offer(c);
        for (int i = 0; i < MAXN; i++) {
            Arrays.fill(distMap[i], Integer.MAX_VALUE);
            Arrays.fill(visited[i], 0);
        }
        visited[startX][startY] = 1;
        distMap[startX][startY] = 0;
        while (!q.isEmpty()) {
            c = q.poll();
            if (c.dist > T) break;
            for (int k = 0; k < 4; k++) {
                int nx = c.row + dirX[k], ny = c.col + dirY[k];
                if (validPos(nx, ny) && gridA[nx][ny] != 'Y' && visited[nx][ny] == 0) {
                    visited[nx][ny] = 1;
                    distMap[nx][ny] = c.dist + 1;
                    q.offer(new Cell(nx, ny, c.dist + 1));
                }
            }
        }
    }

    static void computeDist2(FlowSolver solver, int i, int j, int T) {
        Queue<Cell> q = new LinkedList<>();
        Cell c = new Cell(i, j, 0);
        for (int k = 0; k < MAXN; k++) {
            Arrays.fill(visited[k], 0);
        }
        visited[i][j] = 1;
        q.offer(c);
        while (!q.isEmpty()) {
            c = q.poll();
            if (c.dist > T) break;
            if (distMap[c.row][c.col] < c.dist) continue;
            if ((distMap[c.row][c.col] == c.dist && gridB[c.row][c.col] < '1') || gridB[c.row][c.col] > '9') continue;
            if (gridB[c.row][c.col] >= '1' && gridB[c.row][c.col] <= '9') {
                if (c.row != i || c.col != j)
                    solver.addEdge(getID(i, j), getID(c.row, c.col) + n * n, INF);
                if (distMap[c.row][c.col] == c.dist) continue;
            }
            for (int k = 0; k < 4; k++) {
                int nx = c.row + dirX[k], ny = c.col + dirY[k];
                if (validPos(nx, ny) && gridA[nx][ny] != 'Y' && visited[nx][ny] == 0) {
                    visited[nx][ny] = 1;
                    q.offer(new Cell(nx, ny, c.dist + 1));
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                gridA[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                gridB[i][j] = line.charAt(j - 1);
            }
        }
        int s = 0, e = 2 * n * n + 1;
        FlowSolver solver = new FlowSolver();
        solver.setup(e + 1);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (gridA[i][j] >= '1' && gridA[i][j] <= '9') {
                    solver.addEdge(s, getID(i, j), gridA[i][j] - '0');
                }
                if (gridA[i][j] == 'Z') {
                    startX = i; startY = j;
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                solver.addEdge(getID(i, j), getID(i, j) + n * n, INF);
                if (gridB[i][j] >= '1' && gridB[i][j] <= '9') {
                    solver.addEdge(getID(i, j) + n * n, e, gridB[i][j] - '0');
                }
            }
        }
        computeDist1(solver, startX, startY, T);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (gridA[i][j] >= '1' && gridA[i][j] <= '9') {
                    computeDist2(solver, i, j, T);
                }
            }
        }
        int res = solver.computeMaxFlow(s, e);
        System.out.println(res);
    }
}
